// Simple endless runner based on IDEA.md
// Canvas with id="game" must exist in the HTML.
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const width = canvas.width = 800;
  const height = canvas.height = 200;

  // Player definition
  const player = {
    x: 50,
    y: height - 40,
    w: 30,
    h: 30,
    vy: 0,
    jumpStrength: -8,
    gravity: 0.4,
    onGround: true,
    draw() {
      ctx.fillStyle = '#0f0';
      ctx.fillRect(this.x, this.y, this.w, this.h);
    },
    update() {
      this.vy += this.gravity;
      this.y += this.vy;
      if (this.y + this.h >= height) {
        this.y = height - this.h;
        this.vy = 0;
        this.onGround = true;
      } else {
        this.onGround = false;
      }
    },
    jump() {
      if (this.onGround) {
        this.vy = this.jumpStrength;
        this.onGround = false;
      }
    }
  };

  // Input handling
  window.addEventListener('keydown', e => {
    if (e.code === 'Space' || e.code === 'ArrowUp') player.jump();
  });

  // Obstacles
  const obstacles = [];
  const obstacleSpeed = 3;
  const spawnInterval = 120; // frames
  let frameCount = 0;
  function spawnObstacle() {
    const type = Math.random() < 0.5 ? 'spike' : 'gap';
    if (type === 'spike') {
      const size = 20 + Math.random() * 20;
      obstacles.push({ x: width, y: height - size, w: size, h: size, type: 'spike' });
    } else {
      const gapWidth = 30 + Math.random() * 30;
      obstacles.push({ x: width + gapWidth, y: height, w: gapWidth, h: 0, type: 'gap' });
    }
  }

  // Collision detection
  function checkCollision(ob) {
    if (ob.type === 'spike') {
      return !(player.x + player.w < ob.x || player.x > ob.x + ob.w || player.y + player.h < ob.y || player.y > ob.y + ob.h);
    }
    // gaps are handled by checking if player is over void
    if (ob.type === 'gap') {
      const overGap = player.x + player.w > ob.x && player.x < ob.x + ob.w;
      const onGround = player.y + player.h >= height;
      return overGap && onGround;
    }
    return false;
  }

  let gameOver = false;
  let score = 0;

  function update() {
    if (gameOver) return;
    frameCount++;
    if (frameCount % spawnInterval === 0) spawnObstacle();
    player.update();
    // Move obstacles
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const ob = obstacles[i];
      ob.x -= obstacleSpeed;
      if (checkCollision(ob)) { gameOver = true; }
      // Remove off‑screen
      if (ob.x + ob.w < 0) obstacles.splice(i, 1);
    }
    score++;
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // ground line
    ctx.fillStyle = '#555';
    ctx.fillRect(0, height - 10, width, 10);
    player.draw();
    // draw obstacles
    ctx.fillStyle = '#f00';
    obstacles.forEach(ob => {
      if (ob.type === 'spike') {
        ctx.fillRect(ob.x, ob.y, ob.w, ob.h);
      }
    });
    // score
    ctx.fillStyle = '#fff';
    ctx.font = '16px monospace';
    ctx.fillText('Score: ' + score, 10, 20);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#ff0';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

  function loop() {
    update();
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  loop();
})();
